for a, size, name, conf in FUNCS:
    ea = addr(a)
    fn = fm.getFunctionAt(ea)
    if fn is None:
        fn = createFunction(ea, name)
        if fn is not None:
            created += 1
    if fn is not None and not name.startswith("func_"):
        fn.setName(name, SourceType.IMPORTED)
        renamed += 1
    if fn is not None:
        setPlateComment(ea, "psxrecomp: confidence=%s" % conf)

for a, what in UNRESOLVED:
    createBookmark(addr(a), "psxrecomp", "unresolved %s" % what)

print("psxrecomp: %d functions created, %d named, %d unresolved "
      "indirect sites bookmarked" % (created, renamed, len(UNRESOLVED)))
